  function createGame(options={}){const seed=String(options.seed||'worldforge-battle-v1'),state={version:1,status:'playing',winner:null,seed,turn:1,currentPlayer:'player',nextId:1,players:{player:playerState('player',(options.decks?.player||SAMPLE_DECKS.player).map(normalizeCard),seed),opponent:playerState('opponent',(options.decks?.opponent||SAMPLE_DECKS.opponent).map(normalizeCard),seed)},log:[]};drawCard(state,'player',RULES.startingHand);drawCard(state,'opponent',RULES.startingHand);state.players.player.maxMana=1;state.players.player.mana=1;addLog(state,'实验对战开始。你先手。');return state}
  function fail(message){const error=new Error(message);error.code='ILLEGAL_BATTLE_ACTION';throw error}
