  function healHero(state,playerId,amount){const owner=state.players[playerId];owner.health=Math.min(owner.maxHealth,owner.health+Math.max(0,amount))}
  function damageMinion(state,minion,amount){if(amount<=0)return 0;if(minion.shield){minion.shield=false;addLog(state,`${minion.name}的隔绝抵消了这次伤害。`);return 0}minion.health-=amount;return amount}
  function resolveEffect(state,ownerId,effect,sourceName){const normalized=normalizeEffect(effect);if(!normalized)return;if(normalized.operation==='deal_damage'){const target=normalized.target==='self_hero'?ownerId:opponent(ownerId);damageHero(state,target,normalized.amount);addLog(state,`${sourceName}对${state.players[target].name}造成 ${normalized.amount} 点伤害。`)}else if(normalized.operation==='heal'){const target=normalized.target==='enemy_hero'?opponent(ownerId):ownerId;healHero(state,target,normalized.amount);addLog(state,`${sourceName}为${state.players[target].name}恢复 ${normalized.amount} 点生命。`)}else if(normalized.operation==='draw_card'){drawCard(state,ownerId,normalized.amount)}}
  function cleanupDeaths(state){let steps=0,found=true;while(found&&steps<RULES.maxResolutionSteps){found=false;steps+=1;for(const ownerId of ['player','opponent']){const board=state.players[ownerId].board;for(let index=board.length-1;index>=0;index-=1){const minion=board[index];if(minion.health>0)continue;board.splice(index,1);found=true;addLog(state,`${minion.name}被消灭。`);const echo=usage(minion,KEYWORDS.echo.id),effect=echo?.params?.effect;if(effect)resolveEffect(state,ownerId,effect,`${minion.name}的余响`)}}checkWinner(state)}if(steps>=RULES.maxResolutionSteps)fail('结算步数超过安全上限。')}
  function checkWinner(state){const playerDead=state.players.player.health<=0,opponentDead=state.players.opponent.health<=0;if(!playerDead&&!opponentDead)return;if(playerDead&&opponentDead){state.status='finished';state.winner='draw';return}state.status='finished';state.winner=playerDead?'opponent':'player'}
  function playCard(state,playerId,handIndex){assertTurn(state,playerId);const owner=state.players[playerId],index=Number(handIndex);if(!Number.isInteger(index)||!owner.hand[index])fail('手牌不存在。');const card=owner.hand[index];if(card.cost>owner.mana)fail('资源不足。');if(card.type==='minion'&&owner.board.length>=RULES.maxBoard)fail('随从栏已满。');owner.mana-=card.cost;owner.hand.splice(index,1);if(card.type==='minion'){const minion={...clone(card),maxHealth:card.health,summonedTurn:state.turn,attacked:false,shield:hasKeyword(card,KEYWORDS.isolate.id)};owner.board.push(minion);addLog(state,`${owner.name}打出了${card.name}。`)}else{addLog(state,`${owner.name}使用了${card.name}。`);resolveEffect(state,playerId,card.effect,card.name);cleanupDeaths(state)}return state}
